//! Offline MITRE ATT&CK technique names for the ids rules cite. The table is
//! generated by `scripts/generate-mitre-attack.py` from the ATT&CK Enterprise
//! STIX bundle; its terms are in THIRD-PARTY-NOTICES.md.
use std::sync::OnceLock;

const TABLE: &str = include_str!("../assets/mitre_attack_enterprise.tsv");

fn entries() -> &'static [(&'static str, &'static str)] {
    static ENTRIES: OnceLock<Vec<(&'static str, &'static str)>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        let mut rows: Vec<_> = TABLE
            .lines()
            .filter(|line| !line.starts_with('#'))
            .filter_map(|line| line.split_once('\t'))
            .collect();
        rows.sort_unstable();
        rows
    })
}

fn name(id: &str) -> Option<&'static str> {
    let rows = entries();
    rows.binary_search_by(|(key, _)| (*key).cmp(id))
        .ok()
        .map(|index| rows[index].1)
}

/// The technique's name; a sub-technique reads "Parent: Sub-technique" as
/// ATT&CK writes it. `None` for an id the bundled table does not know.
pub fn technique_name(id: &str) -> Option<String> {
    let id = id.trim().to_ascii_uppercase();
    let sub = name(&id)?;
    match id.split_once('.') {
        Some((parent, _)) => Some(match name(parent) {
            Some(parent) => format!("{parent}: {sub}"),
            None => sub.to_owned(),
        }),
        None => Some(sub.to_owned()),
    }
}

/// "T1059 Command and Scripting Interpreter"; the bare id when it is unknown.
pub fn technique_label(id: &str) -> String {
    match technique_name(id) {
        Some(name) => format!("{id} {name}"),
        None => id.to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn techniques_and_sub_techniques_have_names_and_unknown_ids_stay_bare() {
        assert_eq!(
            technique_label("T1059"),
            "T1059 Command and Scripting Interpreter"
        );
        assert_eq!(
            technique_label("T1059.004"),
            "T1059.004 Command and Scripting Interpreter: Unix Shell"
        );
        assert_eq!(
            technique_name("t1055.008")
                .as_deref()
                .map(|n| n.starts_with("Process Injection")),
            Some(true)
        );
        assert_eq!(technique_label("T9999"), "T9999");
        assert_eq!(technique_label("DET0508"), "DET0508");
        assert!(entries().len() > 600);
    }
}
